package main

import (
	_ "embed"
	"net/http"

	"github.com/nice-platform/nice/pkg/nicetoken"
)

// serviceSlug is the slug registered in the NICE catalog. Tokens for this
// service carry it as aud, and every permission name starts with it.
const serviceSlug = "inventaris"

const (
	permRead   = serviceSlug + ".items.read"
	permCreate = serviceSlug + ".items.create"
	permEdit   = serviceSlug + ".items.edit"
	permDelete = serviceSlug + ".items.delete"
)

// openAPIDoc is generated by `make swag` from the annotations in items.go and main.go.
//
//go:embed docs/swagger.json
var openAPIDoc []byte

// route is one item operation. The same table registers the routes and is
// compared with openAPIDoc in the tests, so the permission the service enforces
// cannot drift from the one NICE imports.
type route struct {
	Method     string
	Pattern    string
	Permission string
	Sensitive  bool
	Handler    http.HandlerFunc
}

func (a *api) routes() []route {
	return []route{
		{http.MethodGet, "/items", permRead, false, a.listItems},
		{http.MethodPost, "/items", permCreate, false, a.createItem},
		{http.MethodGet, "/items/{id}", permRead, false, a.getItem},
		{http.MethodPut, "/items/{id}", permEdit, false, a.updateItem},
		{http.MethodDelete, "/items/{id}", permDelete, true, a.deleteItem},
	}
}

// newHandler assembles CORS -> mux. /healthz and /openapi.json are public;
// every item route verifies the token and then its permission.
func newHandler(v *nicetoken.Verifier, store *Store, corsOrigins []string) http.Handler {
	a := &api{store: store}
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", healthz)
	mux.HandleFunc("GET /openapi.json", serveOpenAPI)
	for _, rt := range a.routes() {
		var opts []nicetoken.RequireOption
		if rt.Sensitive {
			opts = append(opts, nicetoken.Sensitive())
		}
		mux.Handle(rt.Method+" "+rt.Pattern, v.Middleware(v.Require(rt.Permission, opts...)(rt.Handler)))
	}
	return withCORS(corsOrigins, mux)
}

// healthz never calls NICE, so the NICE health probe sees this service alone.
func healthz(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func serveOpenAPI(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	_, _ = w.Write(openAPIDoc)
}
